        _stuckRunning.allMatches(screen),
        isEmpty,
        reason: 'no live job remains — the count drained to zero:\n$screen',
      );

      await harness.runSlashCommand('/exit');
      await harness.pty.exitCode.timeout(
        const Duration(seconds: 15),
        onTimeout: () => -1,
      );
    },
  );
}

