      _stripTrailingComment(line),
];

String _stripTrailingComment(String line) {
  final idx = line.indexOf('//');
  if (idx <= 0) return line;
  if (line[idx - 1] == ':') return line; // scheme:// in a string literal
  return line.substring(0, idx);
}

